if doc.is_new() and doc.item_group:
    pattern = frappe.db.get_value("Item Group", doc.item_group, "custom_naming_series")
    if pattern:
        prefix = pattern
        digits = 5
        dot_idx = pattern.rfind(".#")
        if dot_idx >= 0:
            prefix = pattern[:dot_idx]
            hash_part = pattern[dot_idx:]
            count = hash_part.count("#")
            if count:
                digits = count

        existing = frappe.get_all("Item", filters={"item_code": ["like", prefix + "%"]}, pluck="item_code")
        max_num = 0
        for code in existing:
            num_str = code[len(prefix):]
            if num_str.isdigit():
                max_num = max(max_num, int(num_str))

        doc.item_code = prefix + str(max_num + 1).zfill(digits)
        doc.name = doc.item_code
